CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA public;

CREATE EXTENSION IF NOT EXISTS pgrouting WITH SCHEMA public;

CREATE FUNCTION public.fragilidad(pga_g double precision, mediana double precision, beta double precision, sigma double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT 0.5 * (1 + erf(ln(pga_g / mediana) / sqrt(beta ^ 2 + sigma ^ 2) / sqrt(2)))
$$;

CREATE FUNCTION public.pga_youngs(dist_epi_km double precision, mag double precision, prof_km double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT exp(0.2418 + 1.414 * mag
               - 2.552 * ln(sqrt(dist_epi_km ^ 2 + prof_km ^ 2) + 1.7818 * exp(0.554 * mag))
               + 0.00607 * prof_km)
$$;

CREATE FUNCTION public.prob_falla_sismo(dist_epi_km double precision, mag double precision, prof_km double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    AS $$
    WITH a AS (SELECT pga_youngs(dist_epi_km, mag, prof_km) AS pga,
                      1.45 - 0.1 * least(mag, 8) AS sigma),
         p AS (SELECT fragilidad(pga, 0.24, 0.25, sigma) AS leve,
                      fragilidad(pga, 0.33, 0.20, sigma) AS moderado,
                      fragilidad(pga, 0.58, 0.15, sigma) AS extensivo,
                      fragilidad(pga, 0.89, 0.15, sigma) AS completo
               FROM a)
    SELECT 0.04 * (leve - moderado) + 0.12 * (moderado - extensivo)
         + 0.50 * (extensivo - completo) + 0.80 * completo
    FROM p
$$;

CREATE TABLE public.camino_sin_postacion (
    gid integer NOT NULL,
    id_orig text,
    geom public.geometry(LineString,4326)
);

CREATE SEQUENCE public.camino_sin_postacion_gid_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.camino_sin_postacion_gid_seq OWNED BY public.camino_sin_postacion.gid;

CREATE TABLE public.fibra_optica (
    gid integer NOT NULL,
    id_orig text,
    geom public.geometry(LineString,4326)
);

CREATE SEQUENCE public.fibra_optica_gid_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.fibra_optica_gid_seq OWNED BY public.fibra_optica.gid;

CREATE TABLE public.nodos_clave (
    id integer NOT NULL,
    nombre text NOT NULL,
    tipo text,
    rol text,
    justificacion text,
    fuente text,
    geom public.geometry(Point,4326),
    vertice bigint
);

CREATE TABLE public.postacion_electrica (
    gid integer NOT NULL,
    id_orig text,
    geom public.geometry(LineString,4326)
);

CREATE SEQUENCE public.postacion_electrica_gid_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.postacion_electrica_gid_seq OWNED BY public.postacion_electrica.gid;

CREATE TABLE public.red (
    id bigint NOT NULL,
    id_base bigint,
    capa text NOT NULL,
    sintetico boolean NOT NULL,
    geom public.geometry(LineString,32719),
    source bigint,
    target bigint,
    largo_m double precision,
    cost double precision,
    reverse_cost double precision,
    prob_falla double precision DEFAULT 0 NOT NULL,
    dist_epicentro_km double precision,
    pga_g double precision
);

CREATE SEQUENCE public.red_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.red_id_seq OWNED BY public.red.id;

CREATE TABLE public.red_vertices_pgr (
    id bigint NOT NULL,
    cnt integer,
    chk integer,
    ein integer,
    eout integer,
    the_geom public.geometry(Point,32719)
);

CREATE SEQUENCE public.red_vertices_pgr_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.red_vertices_pgr_id_seq OWNED BY public.red_vertices_pgr.id;

CREATE TABLE public.sismo (
    id text NOT NULL,
    lugar text,
    magnitud double precision,
    tipo_magnitud text,
    fecha_utc timestamp with time zone,
    profundidad_km double precision,
    url text,
    geojson jsonb,
    geom public.geometry(Point,4326)
);

CREATE TABLE public.trayecto_ferry (
    gid integer NOT NULL,
    id_orig text,
    geom public.geometry(LineString,4326)
);

CREATE SEQUENCE public.trayecto_ferry_gid_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.trayecto_ferry_gid_seq OWNED BY public.trayecto_ferry.gid;

ALTER TABLE ONLY public.camino_sin_postacion ALTER COLUMN gid SET DEFAULT nextval('public.camino_sin_postacion_gid_seq'::regclass);

ALTER TABLE ONLY public.fibra_optica ALTER COLUMN gid SET DEFAULT nextval('public.fibra_optica_gid_seq'::regclass);

ALTER TABLE ONLY public.postacion_electrica ALTER COLUMN gid SET DEFAULT nextval('public.postacion_electrica_gid_seq'::regclass);

ALTER TABLE ONLY public.red ALTER COLUMN id SET DEFAULT nextval('public.red_id_seq'::regclass);

ALTER TABLE ONLY public.red_vertices_pgr ALTER COLUMN id SET DEFAULT nextval('public.red_vertices_pgr_id_seq'::regclass);

ALTER TABLE ONLY public.trayecto_ferry ALTER COLUMN gid SET DEFAULT nextval('public.trayecto_ferry_gid_seq'::regclass);









