CREATE INDEX camino_sin_postacion_geom_idx ON public.camino_sin_postacion USING gist (geom);

CREATE INDEX fibra_optica_geom_idx ON public.fibra_optica USING gist (geom);

CREATE INDEX postacion_electrica_geom_idx ON public.postacion_electrica USING gist (geom);

CREATE INDEX red_geom_idx ON public.red USING gist (geom);

CREATE INDEX red_source_idx ON public.red USING btree (source);

CREATE INDEX red_target_idx ON public.red USING btree (target);

CREATE INDEX red_vertices_pgr_the_geom_idx ON public.red_vertices_pgr USING gist (the_geom);

